          <IonFooter className="ion-padding">
            <IonButton expand="block" onClick={handleUpdate} disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : 'Actualizar'}
            </IonButton>
            <IonButton expand="block" fill="outline" onClick={() => setShowEditModal(false)} className="ion-margin-top">
              Cancelar
            </IonButton>
          </IonFooter>
        </IonModal>

        {/* Delete Alert */}
        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header="Confirmar Eliminación"
          message={`¿Está seguro de que desea eliminar al proveedor "${selectedSupplier?.supplierName}"?`}
          buttons=[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: handleDelete, cssClass: 'danger' },
          ]
        />
      </IonContent>
    </IonPage>
  );
};

export default SupplierPage;
